#!/usr/bin/env bash
set -euo pipefail

usage() {
  printf '用法：%s <目录> [扩展名]\n' "${0##*/}" >&2
}

count_files() {
  local dir=$1
  local ext=${2:-*}
  local -i total=0
  while IFS= read -r -d '' _; do ((total += 1)); done < <(find "$dir" -type f -name "*.$ext" -print0)
  printf '%d\n' "$total"
}

dir="${1:-.}"
usage
printf '%s 下 .%s 文件数：%s\n' "$dir" "${2:-*}" "$(count_files "$dir" "${2:-*}")"

#!/usr/bin/env bash
set -euo pipefail

verbose=false
output=""

while getopts ":vo:h" opt; do
  case "$opt" in
    v) verbose=true ;;
    o) output=$OPTARG ;;
    h) echo "用法：$0 [-v] [-o 文件]"; exit 0 ;;
    :) echo "选项 -$OPTARG 需要参数" >&2; exit 2 ;;
    \?) echo "未知选项 -$OPTARG" >&2; exit 2 ;;
  esac
done
shift $((OPTIND - 1))

printf 'verbose=%s output=%s 剩余参数=%d\n' "$verbose" "${output:-未指定}" "$#"
printf '剩余参数列表：%s\n' "$*"

#!/usr/bin/env bash
set -euo pipefail

log_info() { printf '[%s] INFO  %s\n' "$(date +%T)" "$*"; }
log_warn() { printf '[%s] WARN  %s\n' "$(date +%T)" "$*" >&2; }

retry() {
  local -i attempts=$1
  shift
  local -i i=0
  until "$@"; do
    ((i += 1))
    [[ $i -ge $attempts ]] && { log_warn "重试 $attempts 次仍失败：$*"; return 1; }
    sleep 1
  done
}

retry 3 test -f /etc/hosts
log_info "组合函数执行完成"
log_info "当前内核 $(uname -r)"

#!/usr/bin/env bash
set -euo pipefail

# 模块前缀 + 单一入口，模拟可复用库
db_connect() { printf '连接 %s\n' "${1:-default.db}"; }
db_query()   { printf '执行查询：%s\n' "$1"; }
db_close()   { printf '关闭连接\n'; }

main() {
  local -r dsn="${1:-app.db}"
  db_connect "$dsn"
  db_query "select count(*) from users"
  db_close
}

main "$@"

#!/usr/bin/env bats
# 运行：bats tests/math.bats

setup() {
  work="${BATS_TMPDIR}/math-$$"
  mkdir -p "$work"
  add() { echo $(( $1 + $2 )); }
  divide() { (( $2 == 0 )) && { echo "除零" >&2; return 1; }; echo $(( $1 / $2 )); }
}

teardown() {
  rm -rf "$work"
}

@test "add 返回两数之和" {
  [ "$(add 2 3)" -eq 5 ]
}

@test "divide 拒绝除零" {
  run divide 8 0
  [ "$status" -ne 0 ]
  [[ "$output" == *"除零"* ]]
}

#!/usr/bin/env bash
set -euo pipefail

# 配置与逻辑分离：环境变量优先，其次默认值
config_load() {
  : "${APP_HOST:=127.0.0.1}"
  : "${APP_PORT:=8080}"
  : "${APP_LOG_LEVEL:=info}"
}

main() {
  config_load
  printf 'http://%s:%s 日志级别=%s\n' "$APP_HOST" "$APP_PORT" "$APP_LOG_LEVEL"
}

# 仅直接执行时运行，被 source 时只导出函数
if [[ ${BASH_SOURCE[0]} == "$0" ]]; then
  main "$@"
fi
